  <div id="app" aria-live="polite"></div>

  <script>
    const featuredProducts = [
      {
        name: "Halo Speaker",
        category: "Audio",
        description: "Minimal wireless sound with room-filling bass and a sculpted aluminum finish.",
        price: "$179",
        accent: "dark"
      },
      {
        name: "Arc Lamp",
        category: "Home",
        description: "A soft-glow lamp designed to warm shelves, desks, and reading corners instantly.",
        price: "$124",
        accent: "light"
      },
      {
        name: "Drift Chair",
        category: "Living",
        description: "An ergonomic lounge silhouette wrapped in tactile fabric for everyday comfort.",
        price: "$349",
        accent: "warm"
      }
    ];

    const deals = [
      {
        title: "Spring living refresh",
        detail: "Save 25% on seating, side tables, and soft lighting.",
        code: "LIVING25"
      },
      {
        title: "Two-day audio event",
        detail: "Bundle speakers and headphones for an extra 15% off.",
        code: "SOUND15"
      },
      {
        title: "Free shipping upgrade",
        detail: "Priority delivery on orders over $150 this week only.",
        code: "FASTLANE"
      }
    ];

    const editorial = [
      {
        label: "Journal",
        title: "How to style a lighter, calmer workspace",
        description: "Layer texture, indirect light, and modular storage to make small rooms feel expansive."
      },
      {
        label: "Guide",
        title: "The weekend reset: five essentials for your home",
        description: "A quick edit of products and rituals that make your routine feel polished and easy."
      },
      {
        label: "Story",
        title: "Inside the design language of modern retail",
        description: "Why balanced typography, generous spacing, and tactile materials create stronger product moments."
      }
    ];

    function Header() {
      return `
        <header class="site-header">
          <div class="shell site-header__inner">
            <a class="brand" href="#top" aria-label="Northstar Goods home">
              <span class="brand__mark" aria-hidden="true">N</span>
              <span>Northstar Goods</span>
            </a>
            <nav class="site-nav" aria-label="Primary">
              <a href="#featured">Featured</a>
              <a href="#deals">Deals</a>
              <a href="#journal">Editorial</a>
              <a href="#membership">Membership</a>
            </nav>
            <div class="header-actions">
              <a class="ghost-button" href="#journal">Read stories</a>
              <a class="pill-button" href="#featured">Shop now</a>
            </div>
          </div>
        </header>
      `;
    }

    function HeroSection() {
      return `
        <section class="hero" id="top" aria-label="Highlights">
          <article class="hero__panel">
            <span class="eyebrow">New season drop</span>
            <div class="hero__copy">
              <h1>Retail design that feels elevated, useful, and ready for daily life.</h1>
              <p>
                Discover a curated mix of home, audio, and lifestyle essentials chosen for timeless form,
                warm materials, and smart everyday performance.
              </p>
            </div>
            <div class="hero__actions">
              <a class="pill-button" href="#featured">Explore featured picks</a>
              <a class="ghost-button" href="#deals">See current offers</a>
            </div>
            <div class="hero__meta" aria-label="Brand promises">
              <span>Free shipping over $150</span>
              <span>30-day easy returns</span>
              <span>Editorially curated collections</span>
            </div>
            <div class="hero__visual" aria-hidden="true">
              <div class="hero__product"></div>
              <div class="hero__badge hero__badge--top">
                <strong>4.9/5</strong>
                <span>Top-rated essentials</span>
              </div>
              <div class="hero__badge hero__badge--bottom">
                <strong>48 hours</strong>
                <span>Fast dispatch on bestsellers</span>
              </div>
            </div>
          </article>
          <aside class="hero__stats" aria-label="Performance highlights">
            <div class="stat-card">
              <span class="eyebrow">Curated collection</span>
              <strong>120+</strong>
              <p>New arrivals built around quiet luxury, useful upgrades, and durable materials.</p>
            </div>
            <div class="stat-card">
              <span class="eyebrow">Members save more</span>
              <strong>15%</strong>
              <p>Exclusive member pricing, early-access launches, and tailored editorial recommendations.</p>
            </div>
            <div class="stat-card" id="membership">
              <span class="eyebrow">Editorial-led retail</span>
              <strong>Weekly</strong>
              <p>Fresh stories, buying guides, and styling ideas that connect products to everyday routines.</p>
            </div>
          </aside>
        </section>
      `;
    }

    function ProductCard(product) {
      const visualClass = product.accent === "light"
        ? "product-visual product-visual--light"
        : product.accent === "warm"
          ? "product-visual product-visual--warm"
          : "product-visual";

      return `
        <article class="product-card">
          <div class="product-card__media" aria-hidden="true">
            <div class="${visualClass}"></div>
          </div>
          <div class="product-card__body">
            <div class="product-card__meta">
