              </p>
            </div>
            <a class="ghost-button" href="#membership">Join membership</a>
          </div>
          <div class="product-grid">
            ${featuredProducts.map(ProductCard).join("")}
          </div>
        </section>
      `;
    }

    function DealsSection() {
      return `
        <section class="deal-strip" id="deals" aria-labelledby="deals-heading">
          <div class="deal-strip__copy">
            <span class="eyebrow">Deals worth catching</span>
            <h2 id="deals-heading">Smart savings on the pieces people are shopping right now.</h2>
            <p>
              Limited-time offers across audio, furniture, and home accents, created to make seasonal upgrades
              feel immediate and attainable.
            </p>
            <div class="hero__actions">
              <a class="pill-button" href="#featured">Shop discounted picks</a>
            </div>
          </div>
          <div class="deal-strip__list">
            <span class="eyebrow">Current promotions</span>
            <div class="deal-offers">
              ${deals.map((deal) => `
                <article class="deal-offer">
                  <div>
                    <strong>${deal.title}</strong>
                    <p>${deal.detail}</p>
                  </div>
                  <span>${deal.code}</span>
                </article>
              `).join("")}
            </div>
          </div>
        </section>
      `;
    }

    function EditorialCard(item) {
      return `
        <article class="editorial-card">
          <div class="editorial-card__image" aria-hidden="true">
            <div class="editorial-card__frame"></div>
          </div>
          <div class="editorial-card__body">
            <div class="editorial-card__meta">
              <span>${item.label}</span>
              <span>6 min read</span>
            </div>
            <h3>${item.title}</h3>
            <p>${item.description}</p>
          </div>
        </article>
      `;
    }

    function EditorialSection() {
      return `
        <section class="section-card" id="journal" aria-labelledby="journal-heading">
          <div class="section-header">
            <div>
              <span class="eyebrow">Editorial content</span>
              <h2 id="journal-heading">Stories that make shopping feel intentional.</h2>
              <p>
                We pair commerce with inspiration through short reads, practical guides, and behind-the-scenes
                brand storytelling.
              </p>
            </div>
            <a class="ghost-button" href="#top">Back to top</a>
          </div>
          <div class="editorial-grid">
            ${editorial.map(EditorialCard).join("")}
          </div>
        </section>
      `;
    }

    function NewsletterSection() {
      return `
        <section class="newsletter" aria-labelledby="newsletter-heading">
          <div>
            <span class="eyebrow">Stay in the loop</span>
            <h2 id="newsletter-heading">Get launches, offers, and design notes in one calm weekly email.</h2>
            <p>
              Product drops, home styling advice, and members-only promotions sent with a light touch.
            </p>
          </div>
          <form class="newsletter__form">
            <label class="sr-only" for="email-input">Email address</label>
            <input id="email-input" type="email" placeholder="Email address" aria-label="Email address">
            <button class="pill-button" type="submit">Subscribe</button>
          </form>
        </section>
      `;
    }

    function Footer() {
      return `
        <footer class="site-footer">
          <div class="shell site-footer__inner">
            <span>&copy; 2026 Northstar Goods</span>
            <span>Clean retail design for modern everyday living.</span>
          </div>
        </footer>
      `;
    }

    function App() {
      return `
        ${Header()}
        <main class="shell">
          ${HeroSection()}
          ${FeaturedProductsSection()}
          ${DealsSection()}
          ${EditorialSection()}
          ${NewsletterSection()}
        </main>
        ${Footer()}
      `;
    }

    document.getElementById("app").innerHTML = App();
    document.querySelector(".newsletter__form").addEventListener("submit", function (event) {
      event.preventDefault();
    });
  </script>
